<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import ScheduledVocabulary from './ScheduledVocabulary.vue'
import DictionaryLookup from './DictionaryLookup.vue'
import {useVocabularyStore} from '../stores/vocabulary'
import {flashcardBack,parseVocabularyBackup} from '../domain/vocabulary'
import {jishoUrl} from '../domain/dictionary'
const props=defineProps<{initialTab?:'scheduled'|'notebook'|'data'}>()
const store=useVocabularyStore(),tab=ref(props.initialTab??'lookup'),filter=ref(''),message=ref(''),error=ref(''),editing=ref(''),note=ref(''),tags=ref(''),cardIndex=ref(0),revealed=ref(false)
const items=computed(()=>store.bookmarks.filter(b=>[b.term,b.note,...b.tags].some(v=>v.toLocaleLowerCase().includes(filter.value.toLocaleLowerCase()))))
const card=computed(()=>items.value.length?items.value[cardIndex.value%items.value.length]:null)
const back=computed(()=>card.value?flashcardBack(card.value):null)
function beginEdit(id:string){const b=store.bookmarks.find(v=>v.id===id);if(!b)return;editing.value=id;note.value=b.note;tags.value=b.tags.join(', ')}
async function save(){try{error.value='';await store.update(editing.value,note.value,tags.value.split(','));editing.value='';message.value='Đã lưu ghi chú cá nhân.'}catch(e){error.value=e instanceof Error?e.message:'Không lưu được ghi chú.'}}
async function remove(id:string){if(!confirm('Xóa bookmark, ghi chú và lịch sử ôn của từ này khỏi thiết bị?'))return;try{await store.remove(id);message.value='Đã xóa bookmark.'}catch{error.value='Không xóa được bookmark.'}}
function download(){const url=URL.createObjectURL(new Blob([store.exportText()],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='brse-vocabulary.json';a.click();URL.revokeObjectURL(url)}
async function upload(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>5_000_000)throw new Error();const text=await file.text();parseVocabularyBackup(text);if(!confirm('Thay thế toàn bộ sổ từ? Dữ liệu Exam/Interview giữ nguyên. Hãy xuất backup hiện tại trước.'))return;await store.importText(text);message.value='Đã khôi phục sổ từ.';error.value='';editing.value='';revealed.value=false}catch{error.value='Không nhập được: file sai schema/version/dữ liệu hoặc không ghi được bộ nhớ. Validation thất bại không thay thế dữ liệu hiện tại.'}finally{input.value=''}}
async function clear(){if(!confirm('Xóa toàn bộ sổ từ, ghi chú và lịch sử ôn? Dữ liệu Exam/Interview giữ nguyên.'))return;try{await store.clear();message.value='Đã xóa sổ từ.';editing.value=''}catch{error.value='Không xóa được sổ từ.'}}
onMounted(()=>store.init())
</script>
<template>
 <div class="japanese-workspace"><div class="eyebrow">NHẬT NGỮ · GUEST LOCAL-FIRST</div><h1 class="page-title">Tra từ & sổ từ vựng</h1><p class="lead">Tra một cụm ngắn, hiểu cách dùng, rồi đưa vào câu trả lời từ trải nghiệm thật.</p>
 <nav class="interview-tabs" aria-label="Điều hướng Nhật ngữ"><button @click="tab='lookup'" :class="{selected:tab==='lookup'}">Tra từ Nhật ngữ</button><button @click="tab='notebook'" :class="{selected:tab==='notebook'}">Sổ từ vựng · {{store.bookmarks.length}}</button><button @click="tab='cards';filter='';revealed=false" :class="{selected:tab==='cards'}">Ôn flashcard</button><button @click="tab='scheduled'" :class="{selected:tab==='scheduled'}">Ôn theo lịch</button><button @click="tab='data'" :class="{selected:tab==='data'}">Backup sổ từ</button></nav>
 <p v-if="store.error" role="alert" class="notice danger">{{store.error}}</p><p v-if="error" role="alert" class="notice danger">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p>
 <ScheduledVocabulary v-if="tab==='scheduled'"/>
 <section v-if="tab==='lookup'" class="card form-card"><DictionaryLookup/></section>
 <template v-if="tab==='notebook'"><label>Lọc sổ từ<input v-model="filter" maxlength="100" placeholder="Từ, tag hoặc ghi chú…"></label><p v-if="!items.length" class="card empty">Chưa có từ phù hợp. Tra từ rồi lưu cụm bạn muốn luyện.</p><div class="vocabulary-list"><article v-for="b in items" :key="b.id" class="card"><div class="section-heading"><h2 lang="ja">{{b.term}}</h2><span class="pill">{{b.source==='AUTHOR_CREATED'?'TỰ BIÊN SOẠN':'THAM CHIẾU JISHO'}}</span></div><p class="hint">{{b.tags.join(' · ')||'Chưa có tag'}} · Ghi chú của bạn, không phải định nghĩa provider được sao chép.</p><p class="learner-note">{{b.note||'Chưa có ghi chú cá nhân.'}}</p><a v-if="b.source==='JISHO_REFERENCE'" :href="jishoUrl(b.term)" target="_blank" rel="noopener noreferrer">Mở truy vấn nguồn Jisho ↗</a><div class="actions"><button @click="beginEdit(b.id)">Sửa ghi chú</button><button @click="remove(b.id)">Xóa bookmark</button></div><form v-if="editing===b.id" @submit.prevent="save"><label>Ghi chú do bạn tự viết<textarea v-model="note" rows="3" maxlength="2000"></textarea></label><label>Tags (ngăn cách bằng dấu phẩy)<input v-model="tags" maxlength="330" placeholder="IT, BrSE, N3"></label><button class="primary" :disabled="store.saving">Lưu ghi chú</button></form></article></div></template>
 <section v-if="tab==='cards'" class="card flashcard"><h2>Ôn từ đã lưu</h2><p class="hint">Flashcard tự do, không đổi lịch ôn hoặc điểm. Chọn Ôn theo lịch nếu muốn lưu mức nhớ và hẹn lần tiếp theo.</p><template v-if="card&&back"><span class="pill">{{(cardIndex%items.length)+1}} / {{items.length}}</span><div class="flashcard-term" lang="ja">{{card.term}}</div><button v-if="!revealed" class="primary" @click="revealed=true">Lật thẻ</button><div v-else data-testid="flashcard-back"><p lang="ja">{{back.reading}}</p><p>{{back.meaning||'Không lưu định nghĩa ngoài. Hãy dùng ghi chú cá nhân hoặc mở lại nguồn để tra cứu.'}}</p><blockquote v-if="back.example" lang="ja">{{back.example}}</blockquote><p class="learner-note">{{back.note||'Chưa có ghi chú cá nhân.'}}</p><button class="primary" @click="cardIndex++;revealed=false">Thẻ tiếp theo →</button></div></template><p v-else>Chưa có từ. Tra và lưu một cụm trước khi ôn.</p></section>
 <template v-if="tab==='data'"><section class="card form-card"><h2>Backup sổ từ riêng biệt</h2><p>Chỉ lưu cụm tra cứu, nguồn tham chiếu, ghi chú/tags và lịch sử ôn theo lịch tự khai. Không lưu định nghĩa/media bên ngoài, CV, transcript hay audio. JSON chưa mã hóa; hãy giữ file riêng tư.</p><div class="actions"><button class="primary" @click="download">Xuất sổ từ JSON</button><label class="file-button">Nhập sổ từ JSON<input type="file" accept="application/json,.json" @change="upload"></label></div><p class="hint">Schema v1 · Tối đa 500 bookmark/5 MB. Import chỉ thay thế sổ từ, không chạm Exam/Interview.</p></section><section class="card form-card"><h2>Xóa dữ liệu sổ từ</h2><button class="danger-button" @click="clear">Xóa toàn bộ sổ từ</button></section></template>
 </div>
</template>
